export type Exercise = { skill: string; prompt: string; answer: string; distractors: [string, string]; why: string; examTask?: number }
export type Lesson = { id: string; title: string; unit: string; time: string; aim: string; text: string[]; example: string; rule: string; task: string; answer: string; choices: string[]; correct: number; rationale: string; explainPrompt: string; examTask?: number }
export type Track = { id: 'base' | 'oge' | 'ege'; name: string; short: string; icon: string; tone: string; description: string; examMinutes: number; examTasks: number; lessons: Lesson[] }
type UnitSeed = { track: Track['id']; unit: string; title: string; aim: string; explanation: string; details: string; example: string; rule: string; exercises: [Exercise, Exercise, Exercise, Exercise] }
const exercise = (skill: string, prompt: string, answer: string, wrongA: string, wrongB: string, why: string, examTask?: number): Exercise => ({ skill, prompt, answer, distractors: [wrongA, wrongB], why, examTask })

