const shuffle = <T,>(items: T[], seed: number): T[] => { const result = [...items]; let value = seed || 1; for (let i = result.length - 1; i > 0; i--) { value = (value * 9301 + 49297) % 233280; const j = Math.floor(value / 233280 * (i + 1)); [result[i], result[j]] = [result[j], result[i]] } return result }
export const generateDictation = (seed = Date.now()) => {
 const choices = shuffle(sentenceBank, seed).slice(0, 5)
 const titles = ['Утро у реки','Листья и ветер','Страница дневника','Наблюдение в пути','После уроков','Город просыпается','Тихий вечер','Дорога домой']
 return { title: `${titles[seed % titles.length]} · вариант ${seed % 99 + 1}`, text: choices.join(' ') }
}
